(function(){'use strict';var endpoints=[["GET", "Discover endpoints", "/api/commission", "Return the Sales Commission endpoint catalog."], ["GET", "List commissions", "/api/commission/commissions", "List calculated commissions with pagination and staff, invoice, client and paid filters."], ["GET", "Get commission", "/api/commission/commissions/:id", "Retrieve one calculated commission."], ["GET", "List policies", "/api/commission/policies", "List commission policies."], ["POST", "Create policy", "/api/commission/policies", "Create a policy with date range, policy type and percentage or ladder settings."], ["GET", "Get policy", "/api/commission/policies/:id", "Retrieve one commission policy."], ["PUT", "Update policy", "/api/commission/policies/:id", "Update a commission policy."], ["DELETE", "Delete policy", "/api/commission/policies/:id", "Delete a commission policy."], ["GET", "List staff assignments", "/api/commission/applicable-staff", "List staff-to-policy assignments."], ["POST", "Create staff assignment", "/api/commission/applicable-staff", "Assign one or more staff members to a policy."], ["GET", "Get staff assignment", "/api/commission/applicable-staff/:id", "Retrieve a staff assignment."], ["PUT", "Update staff assignment", "/api/commission/applicable-staff/:id", "Update a staff assignment."], ["DELETE", "Delete staff assignment", "/api/commission/applicable-staff/:id", "Delete a staff assignment."], ["GET", "List client assignments", "/api/commission/applicable-clients", "List client-to-policy assignments."], ["POST", "Create client assignment", "/api/commission/applicable-clients", "Assign one or more clients to a policy."], ["GET", "Get client assignment", "/api/commission/applicable-clients/:id", "Retrieve a client assignment."], ["PUT", "Update client assignment", "/api/commission/applicable-clients/:id", "Update a client assignment."], ["DELETE", "Delete client assignment", "/api/commission/applicable-clients/:id", "Delete a client assignment."], ["GET", "List hierarchies", "/api/commission/hierarchies", "List salesperson/coordinator commission hierarchies."], ["POST", "Create hierarchy", "/api/commission/hierarchies", "Create a hierarchy using salesman, coordinator and percent."], ["GET", "Get hierarchy", "/api/commission/hierarchies/:id", "Retrieve a hierarchy."], ["PUT", "Update hierarchy", "/api/commission/hierarchies/:id", "Update a hierarchy."], ["DELETE", "Delete hierarchy", "/api/commission/hierarchies/:id", "Delete a hierarchy."], ["GET", "List sales-admin groups", "/api/commission/salesadmin-groups", "List sales-admin/customer-group mappings."], ["POST", "Create sales-admin group", "/api/commission/salesadmin-groups", "Create a sales-admin/customer-group mapping."], ["GET", "Get sales-admin group", "/api/commission/salesadmin-groups/:id", "Retrieve a mapping."], ["PUT", "Update sales-admin group", "/api/commission/salesadmin-groups/:id", "Update a mapping."], ["DELETE", "Delete sales-admin group", "/api/commission/salesadmin-groups/:id", "Delete a mapping."], ["GET", "List receipts", "/api/commission/receipts", "List commission receipts with pagination and filters."], ["POST", "Create receipt", "/api/commission/receipts", "Create a receipt and mark selected commissions as paid."], ["GET", "Get receipt", "/api/commission/receipts/:id", "Retrieve a receipt with commission details."], ["PUT", "Update receipt", "/api/commission/receipts/:id", "Update a receipt and synchronize paid commissions."], ["DELETE", "Delete receipt", "/api/commission/receipts/:id", "Delete a receipt."], ["GET", "Get receipt PDF", "/api/commission/receipts/:id/pdf", "Return the receipt PDF as Base64."], ["POST", "Email receipt", "/api/commission/receipts/:id/email", "Send a receipt message to one or more email addresses."], ["GET", "Get chart data", "/api/commission/chart", "Return yearly commission and paid-commission chart data."], ["POST", "Recalculate commissions", "/api/commission/recalculate", "Recalculate commissions for the supplied invoice_ids."]];
function esc(v){return String(v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]})}
function anchor(m,t){return'api-commission-'+m.toLowerCase()+'-'+t.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')}
function example(m,p){return'curl -X '+m+' -H "authtoken: YOUR_API_TOKEN" "https://yoursite.com'+p.replace(':id','42')+'"'}
function installSection(){var content=document.getElementById('content');if(!content)return false;if(document.getElementById('api-sales-commission'))return true;var section=document.createElement('section');section.id='api-sales-commission';section.innerHTML='<h2>Sales Commission</h2><article><h1>Sales Commission endpoints</h1><div class="row pre-post"><div class="col-md-7 no-float"><div class="endpoint-desc"><p>Manage calculated commissions, policies, staff and client applicability, hierarchies, sales-admin groups, receipts, chart data and recalculation through API v3.</p><p>The Commission module must be active. Authenticate with <code>authtoken</code> and grant the matching Sales Commission method capability.</p></div><div class="table-responsive-wrapper"><table class="table table-hover"><thead><tr><th>Method</th><th>Endpoint</th><th>Operation</th></tr></thead><tbody>'+endpoints.map(function(r){return'<tr><td>'+r[0]+'</td><td><code>'+esc(r[2])+'</code></td><td>'+esc(r[1])+'</td></tr>'}).join('')+'</tbody></table></div></div></div></article>'+endpoints.map(function(r){return'<article id="'+anchor(r[0],r[1])+'"><h1>'+esc(r[1])+'</h1><div class="row pre-post"><div class="col-md-7 no-float"><pre class="full-pre"><span class="typ typ-'+r[0].toLowerCase()+'">'+r[0]+'</span><span class="url">'+esc(r[2])+'</span></pre><div class="endpoint-desc"><p>'+esc(r[3])+'</p></div></div><div class="col-md-4 section-example no-float"><pre class="astro-code catppuccin-mocha" style="background:#1e1e2e;color:#cdd6f4;overflow-x:auto"><code>'+esc(example(r[0],r[2]))+'</code></pre></div></div></article>'}).join('');var target=document.getElementById('api-customers');content.insertBefore(section,target||document.getElementById('api-custom-fields')||null);return true}
function installNav(){var nav=document.querySelector('#sidenav ul.sidenav');if(!nav)return false;if(nav.querySelector('[data-commission-nav]'))return true;var h=document.createElement('li');h.className='nav-header nav-list-item';h.setAttribute('data-commission-nav','true');h.innerHTML='<a href="#api-sales-commission">Sales Commission</a>';nav.appendChild(h);endpoints.forEach(function(r){var i=document.createElement('li');i.className='nav-list-item';i.innerHTML='<a href="#'+anchor(r[0],r[1])+'"><span class="typ-name typ-'+r[0].toLowerCase()+'">'+r[0]+'</span><span class="nav-title">'+esc(r[1])+'</span></a>';nav.appendChild(i)});return true}
function install(){return installSection()&&installNav()}function start(){install();var o=new MutationObserver(install);o.observe(document.documentElement,{childList:true,subtree:true});setTimeout(function(){install();o.disconnect()},5000)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start()}());
